def is_nested(string):
    # A valid nested subsequence exists iff we can find two '[' and two ']'
    # in the order [ [ ] ] as a subsequence (characters can be skipped).
    state = 0
    for ch in string:
        if state == 0 and ch == '[':
            state = 1
        elif state == 1 and ch == '[':
            state = 2
        elif state == 2 and ch == ']':
            state = 3
        elif state == 3 and ch == ']':
            return True
    return False
